"""Largest-remainder allocation of an amount in cents. See task.md."""

from __future__ import annotations


def _is_int(x: object) -> bool:
    return isinstance(x, int) and not isinstance(x, bool)


def allocate(amount: int, weights: list[int]) -> list[int]:
    """Split `amount` cents in proportion to `weights`, one share per weight."""
    if not _is_int(amount) or amount < 0:
        raise ValueError("amount must be a non-negative int")
    weights = list(weights)
    if not weights:
        raise ValueError("weights must not be empty")
    if any(not _is_int(w) or w < 0 for w in weights):
        raise ValueError("weights must be non-negative ints")
    total = sum(weights)
    if total == 0:
        raise ValueError("at least one weight must be non-zero")

    shares = [amount * w // total for w in weights]
    remainders = [amount * w % total for w in weights]
    leftover = amount - sum(shares)
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        shares[i] += 1
    return shares
